function addColumn(cells, value) {
  return [cells[0], cells[1], value, ...cells.slice(2)];
}

function renderSection(header, rows = [], { general = false, insertColumn = false } = {}) {
  const renderedHeader = insertColumn && general ? addColumn(header, '上游新增欄位') : header;
  const renderedRows = insertColumn && general ? rows.map((row) => addColumn(row, '999')) : rows;
  const head = renderedHeader.map((cell, index) => `<th>${index === 0 ? '公司<br>代號' : cell}</th>`).join('');
  const body = renderedRows
    .map((row) => `<tr>${row.map((cell) => `<td>${cell}</td>`).join('')}</tr>`)
    .join('');
  return `<table data-kind="${general ? 'general' : 'special'}"><tr class="tblHead">${head}</tr>${body}</table>`;
}

export function makeSiiQuarterlyFixture(season = 1, { insertGeneralColumn = false } = {}) {
  const rows = season === 1 ? SII_Q1_ROWS : SII_Q2_ROWS;
  return Buffer.from([
    '<html><body>',
    renderSection(BANK_HEADER),
    renderSection(SECURITIES_HEADER),
    renderSection(GENERAL_HEADER, rows, { general: true, insertColumn: insertGeneralColumn }),
    renderSection(FINANCIAL_HOLDING_HEADER),
    renderSection(INSURANCE_HEADER),
    renderSection(OTHER_HEADER),
    '</body></html>',
  ].join(''), 'utf8');
}

export function makeOtcQuarterlyFixture({ insertGeneralColumn = false } = {}) {
  return Buffer.from([
    '<html><body>',
    renderSection(SECURITIES_HEADER),
    renderSection(GENERAL_HEADER, OTC_Q2_ROWS, { general: true, insertColumn: insertGeneralColumn }),
    '</body></html>',
  ].join(''), 'utf8');
}
